/**
 * Benchmark: brute force vs nearest neighbor vs NN + 2-opt.
 *
 * Run with: npm run benchmark
 *
 * Points are generated by a seeded PRNG (mulberry32) inside São Luís's
 * bounding box, so every run produces the exact same instances —
 * numbers are reproducible, not cherry-picked.
 */

import { buildDistanceMatrix } from '../src/core/distanceMatrix.js';
import { nearestNeighbor } from '../src/core/nearestNeighbor.js';
import { twoOpt } from '../src/core/twoOpt.js';
import { bruteForce, BRUTE_FORCE_LIMIT } from '../src/core/bruteForce.js';
import { routeDistance } from '../src/core/routeDistance.js';

/** Deterministic PRNG — same seed, same sequence, reproducible benchmark. */
function mulberry32(seed) {
  return function () {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function generateStops(count, seed = 42) {
  const random = mulberry32(seed);

  // São Luís bounding box (approx).
  const latMin = -2.6;
  const latMax = -2.45;
  const lngMin = -44.35;
  const lngMax = -44.15;

  return Array.from({ length: count }, () => ({
    lat: latMin + random() * (latMax - latMin),
    lng: lngMin + random() * (lngMax - lngMin),
  }));
}

function measure(fn) {
  const start = performance.now();
  const result = fn();
  return { result, ms: performance.now() - start };
}

const sizes = [6, 8, 9, 25, 50, 100, 250, 500];
const rows = [];

for (const n of sizes) {
  const stops = generateStops(n);
  const matrix = buildDistanceMatrix(stops);

  const originalKm = routeDistance(
    Array.from({ length: n }, (_, i) => i),
    matrix
  );

  const nn = measure(() => nearestNeighbor(matrix, 0));
  const nnKm = routeDistance(nn.result, matrix);

  const improved = measure(() => twoOpt(nn.result, matrix));
  const improvedKm = routeDistance(improved.result, matrix);

  const row = {
    n,
    'original (km)': originalKm.toFixed(1),
    'NN (km)': nnKm.toFixed(1),
    'NN+2opt (km)': improvedKm.toFixed(1),
    'saved vs original': `${(((originalKm - improvedKm) / originalKm) * 100).toFixed(1)}%`,
    'heuristic time': `${(nn.ms + improved.ms).toFixed(1)}ms`,
  };

  if (n <= BRUTE_FORCE_LIMIT) {
    const brute = measure(() => bruteForce(matrix));
    const gap = ((improvedKm - brute.result.distance) / brute.result.distance) * 100;

    row['optimal (km)'] = brute.result.distance.toFixed(1);
    row['gap to optimal'] = `${gap.toFixed(2)}%`;
    row['brute force time'] = `${brute.ms.toFixed(1)}ms`;
  } else {
    row['optimal (km)'] = '-';
    row['gap to optimal'] = '-';
    row['brute force time'] = `unfeasible (${n}! permutations)`;
  }

  rows.push(row);
}

console.log('\nroute-optimizer benchmark — seeded points (reproducible)\n');
console.table(rows);

console.log(
  [
    '',
    'Reading the numbers:',
    '- Brute force guarantees the optimum but explodes factorially:',
    '  at n=9 it already evaluates 40,320 permutations; n=15 would take hours.',
    '- NN+2opt stays within a few percent of the optimum on small instances',
    '  (where the optimum is verifiable) and solves n=500 in well under a second.',
    '',
  ].join('\n')
);
